// Persist the untrusted payload to a temp file. We never interpolate the
// log text into a shell command — the scanner reads it from disk.
const fs = require('fs');
const os = require('os');
const path = require('path');
const body = $json.body || {};
const raw = typeof body.log === 'string' ? body.log : JSON.stringify(body, null, 2);
const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'log81-guard-'));
const file = path.join(dir, 'incoming.log');
fs.writeFileSync(file, raw, 'utf8');
return [{ json: { dir, file } }];
